{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create or replace table izf-wh.maplemonk.izf_returns_consolidated as select e.reference_code ,e.Marketplace_LineItem_ID AS SALEORDERITEMCODE ,e.ORDER_ID ,Upper(e.order_status) as order_status ,cast(e.ORDER_DATE as datetime) AS Order_Date ,UPPER(e.marketplace) AS marketplace ,UPPER(e.marketplace) AS MARKETING_CHANNEL ,UPPER(e.marketplace) AS SOURCE ,UPPER(e.PRODUCTNAME) AS PRODUCT_NAME ,e.SKU ,UPPER(e.mapped_category) AS product_category ,e.suborder_quantity as order_quantity ,UPPER(e.CITY) AS City ,UPPER(e.STATE) AS State ,e.pincode ,UPPER(e.COURIER) AS Shipping_Courier ,e.awb ,e.customer_name AS NAME ,e.email AS EMAIL ,cast(null as datetime) as return_requested_date ,case when coalesce(r.return_flag,e.is_refund) = 1 then \'Approved\' else null end as return_approval_status ,(case when coalesce(r.return_flag,e.is_refund) = 1 then (case when (lower(r.return_reason) like \'%rto%\' or lower(r.return_reason) like \'%not delivered%\' or lower(e.shipping_status) like \'%rto%\' or lower(shipping_status) like \'%delivered to origin%\') then \'RTO\' when lower(r.return_reason) like \'%exchange%\' then \'Exchange\' when lower(e.shipping_status) like \'%lost%\' then \'Shipment Lost\' else \'Return\' end) end) return_request_type ,e.is_refund as return_flag ,cast(r.return_date as date) as return_date ,r.RETURNED_QUANTITY as TOTAL_RETURNED_QUANTITY ,e.Payment_mode ,r.return_reason ,e.selling_price ,r.PRODUCTNAME as returned_product_name ,r.RETURNED_PRODUCT_SIZE as returned_product_variant ,r.sku as returned_sku ,r.TOTAL_RETURN_AMOUNT ,e.commonsku ,case when lower(return_reason) like \'%exchange%\' then r.sku else null end as TOTAL_RETURN_TAX ,r.RETURN_AMOUNT_WITHOUT_TAX as TOTAL_RETURN_AMOUNT_EXCL_TAX ,r.suborder_num as returned_item_saleorderitemcode ,case when lower(return_reason) like \'%exchange%\' then r.PRODUCTNAME else null end as exchange_product_name ,case when lower(return_reason) like \'%exchange%\' then r.RETURNED_PRODUCT_SIZE else null end as exchange_product_size ,case when lower(return_reason) like \'%exchange%\' then r.sku else null end as exchange_sku ,case when lower(return_reason) like \'%exchange%\' then e.selling_price else null end as exchange_product_total_price ,e.order_status as oms_order_status from maplemonk.izf_easyecom_fact_items e left join maplemonk.izf_easyecom_returns_intermediate r on e.reference_code = r.reference_code and e.marketplace_lineitem_id = r.suborder_num; CREATE OR REPLACE TABLE izf-wh.maplemonk.izf_returns_count_data as WITH orders as ( SELECT LAST_DAY(date(order_date), MONTH) as order_month, DATE_TRUNC(order_Date, MONTH) as month_first_date, date(order_date) as order_date, marketplace, count(distinct reference_code) as orders_for_the_month, COUNT(DISTINCT CASE WHEN (return_flag = 1 and lower(return_request_type) = \'return\') THEN reference_code END) AS total_returned_orders_for_orders_of_month, sum(case when (return_flag=1 and lower(return_request_type) = \'return\') then 1 else 0 end) as total_returned_items_for_orders_of_month, sum(case when (return_flag=1 and lower(return_request_type) = \'return\') then TOTAL_RETURNED_QUANTITY else 0 end) as total_returned_quantity_for_orders_of_month, count(*) as total_order_items_for_the_month, sum(order_quantity) as total_order_quantity_for_the_month, sum(selling_price) as total_sales FROM izf-wh.maplemonk.izf_returns_consolidated GROUP BY order_month,month_first_date, order_date,marketplace ), returns as ( SELECT LAST_DAY(DATE(return_date), MONTH) as return_month, date(return_date) as return_date, marketplace, COUNT(*) as total_returned_items_received_in_month, count(distinct reference_code) as returned_orders_received_in_month, sum(TOTAL_RETURNED_QUANTITY) as returned_quantity_received_in_month, sum(TOTAL_RETURN_AMOUNT) as total_returned_sales FROM izf-wh.maplemonk.izf_returns_consolidated WHERE return_flag = 1 and lower(return_request_type) = \'return\' GROUP BY return_month,return_date,marketplace ) SELECT o.month_first_date, o.marketplace, o.order_month, o.order_date, o.orders_for_the_month, o.total_order_items_for_the_month, o.total_order_quantity_for_the_month, o.total_returned_orders_for_orders_of_month, o.total_returned_items_for_orders_of_month, o.total_returned_quantity_for_orders_of_month, o.total_sales, r.total_returned_sales, r.return_date, r.total_returned_items_received_in_month, r.returned_orders_received_in_month, r.returned_quantity_received_in_month from orders o LEFT JOIN returns r ON r.return_date = o.order_date and r.marketplace = o.marketplace order by order_date desc;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            